const checkoutState={details:{},delivery:'standard',method:'card',ready:false,receipt:null};
const deliveryStates=['Abia','Adamawa','Akwa Ibom','Anambra','Bauchi','Bayelsa','Benue','Borno','Cross River','Delta','Ebonyi','Edo','Ekiti','Enugu','FCT — Abuja','Gombe','Imo','Jigawa','Kaduna','Kano','Katsina','Kebbi','Kogi','Kwara','Lagos','Nasarawa','Niger','Ogun','Ondo','Osun','Oyo','Plateau','Rivers','Sokoto','Taraba','Yobe','Zamfara'];
const checkoutGlyph=n=>`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><path d="M12 14v3"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h3"/>',bank:'<path d="m3 8 9-5 9 5H3ZM4 21h16M6 11v6M12 11v6M18 11v6"/>',check:'<path d="m5 12 4 4L19 6"/>',package:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5ZM3 8l9 5 9-5M12 13v8M7 5.8l9 5"/>'})[n]||''}</svg>`;
function cleanCart(){bag=bag.flatMap(x=>{const p=products.find(p=>p.id===x.id);if(!p)return [];const options=lengthsFor(p),length=options.includes(Number(x.length))?Number(x.length):options[0],bundles=[1,2,3].includes(Number(x.bundles))?Number(x.bundles):1,qty=Math.max(1,Math.min(99,Math.floor(Number(x.qty)||1)));const base=p.price+(p.cat==='Haircare'?0:(length-options[0])*3500);return [{id:p.id,length,bundles,qty,price:Math.round(base*bundles*(bundles===2?.9:bundles===3?.85:1))}];});}
function checkoutTotals(){const subtotal=bag.reduce((n,x)=>n+x.price*x.qty,0),region=checkoutState.details.state,delivery=region?3500+(region==='Lagos'?0:1500)+(checkoutState.delivery==='express'?2500:0):null;return {subtotal,delivery,total:subtotal+(delivery||0),quantity:bag.reduce((n,x)=>n+x.qty,0)};}
function checkoutSteps(step){return `<ol class="checkout-steps" aria-label="Checkout progress">${['Bag','Delivery','Payment'].map((label,i)=>`<li class="${i===step?'current':i<step?'complete':''}" ${i===step?'aria-current="step"':''}><span class="step-number">${i<step?checkoutGlyph('check'):i+1}</span>${i<step?`<a href="#${i===0?'bag':'checkout'}">${label}</a>`:`<span>${label}</span>`}</li>`).join('')}</ol>`;}
function orderSummary(payment=false){const t=checkoutTotals();return `<aside class="checkout-summary" aria-labelledby="orderSummaryTitle"><div class="checkout-summary-heading"><h2 id="orderSummaryTitle">Your edit.</h2><a class="btn btn-outline-secondary" href="#bag">Edit bag</a></div><p class="summary-subtitle">${t.quantity} ${t.quantity===1?'set':'sets'}, chosen by you.</p><div class="checkout-items">${bag.map(x=>{const p=products.find(p=>p.id===x.id);return `<div class="checkout-item"><img src="assets/${p.img}" alt="" width="72" height="96"><div><h3>${p.name}</h3><p>${p.cat==='Haircare'?'Care essentials':x.length+' inches'} · ${x.bundles} ${p.cat==='Bundles'?'bundle':'piece'}${x.bundles>1?'s':''}</p><span>Quantity ${x.qty}</span></div><b>${money(x.price*x.qty)}</b></div>`}).join('')}</div><dl class="checkout-totals"><div><dt>Subtotal</dt><dd>${money(t.subtotal)}</dd></div><div><dt>Delivery${t.delivery===null?'':checkoutState.delivery==='express'?' · Express':' · Standard'}</dt><dd>${t.delivery===null?'Select your state':money(t.delivery)}</dd></div><div class="checkout-grand-total"><dt>${t.delivery===null?'Total before delivery':'Total'}<small>NGN · Nigerian naira</small></dt><dd>${money(t.total)}</dd></div></dl><p class="checkout-small">Delivery rates and product prices are illustrative. No additional charge is added in this preview.</p><div class="summary-assurance">${checkoutGlyph('package')}<p>Made for your next chapter.<span>Your chosen lengths and set sizes stay with your order.</span></p></div>${payment?`<div class="payment-amount-label">Payment preview only</div>`:''}</aside>`;}
function checkoutField(name,label,{type='text',autocomplete='',optional=false,wide=false,placeholder='',max=120}={}){const value=checkoutState.details[name]||'';return `<div class="checkout-field ${wide?'field-wide':''}"><label for="co-${name}">${label}${optional?'<span>Optional</span>':''}</label><input id="co-${name}" name="${name}" type="${type}" ${type==='tel'?'inputmode="tel"':''} autocomplete="${autocomplete}" maxlength="${max}" value="${escapeHTML(value)}" placeholder="${placeholder}" ${optional?'':'required'} aria-describedby="error-${name}"><p class="field-error" id="error-${name}"></p></div>`;}
function checkoutEmpty(){app.innerHTML=`<div class="wrap checkout-wrap">${checkoutSteps(1)}<div class="empty checkout-empty">${checkoutGlyph('package')}<div class="eyebrow">YOUR NEXT CHAPTER</div><h1>A muse belongs here.</h1><p>Add a style to your bag to start checkout.</p><a class="btn btn-dark primary" href="#shop">Explore the collection</a></div></div>`;}
function checkoutPage(){cleanCart();if(!bag.length){checkoutEmpty();return;}const d=checkoutState.details;app.innerHTML=`<div class="wrap checkout-wrap"><div class="checkout-top"><a class="btn btn-outline-secondary" href="#bag">Back to bag</a><span>${checkoutGlyph('lock')} Checkout preview</span></div>${checkoutSteps(1)}<div class="checkout-heading"><span class="eyebrow">THE FINISHING TOUCH</span><h1>Make it yours.</h1><p>A few details, then you're one step closer to your muse.</p></div><div class="checkout-layout"><form id="deliveryForm" novalidate class="checkout-form"><div id="checkoutErrors" class="checkout-error-summary" role="alert" hidden></div><section class="checkout-panel"><div class="panel-heading"><span class="panel-number">01</span><div><h2>Contact details</h2><p>Where your order updates would arrive.</p></div></div><div class="checkout-fields">${checkoutField('firstName','First name',{autocomplete:'given-name'})}${checkoutField('lastName','Last name',{autocomplete:'family-name'})}${checkoutField('email','Email address',{type:'email',autocomplete:'email',wide:true,placeholder:'you@example.com'})}${checkoutField('phone','Phone number',{type:'tel',autocomplete:'tel',wide:true,placeholder:'0801 234 5678'})}</div></section><section class="checkout-panel"><div class="panel-heading"><span class="panel-number">02</span><div><h2>Delivery address</h2><p>A little luxury, delivered to your door.</p></div></div><div class="checkout-fields"><div class="checkout-field field-wide"><label for="co-country">Country</label><select id="co-country" name="country" autocomplete="country-name"><option>Nigeria</option></select></div>${checkoutField('address','Street address',{autocomplete:'shipping address-line1',wide:true,placeholder:'House number and street name',max:200})}${checkoutField('apartment','Apartment, suite or landmark',{autocomplete:'shipping address-line2',wide:true,optional:true,max:160})}${checkoutField('city','City',{autocomplete:'shipping address-level2'})}<div class="checkout-field"><label for="co-state">State</label><select id="co-state" name="state" autocomplete="shipping address-level1" required aria-describedby="error-state"><option value="">Select a state</option>${deliveryStates.map(s=>`<option ${d.state===s?'selected':''}>${s}</option>`).join('')}</select><p class="field-error" id="error-state"></p></div>${checkoutField('postcode','Postal code',{autocomplete:'shipping postal-code',optional:true})}${checkoutField('notes','Delivery note',{optional:true,wide:true,placeholder:'Anything the courier should know?',max:250})}</div></section><section class="checkout-panel"><div class="panel-heading"><span class="panel-number">03</span><div><h2>Delivery method</h2><p>Choose the pace that suits you.</p></div></div><fieldset class="delivery-options"><legend class="sr-only">Delivery method</legend>${['standard','express'].map(m=>`<label class="choice-card"><input type="radio" name="delivery" value="${m}" ${checkoutState.delivery===m?'checked':''}><span><b>${m==='standard'?'Standard delivery':'Express delivery'}</b><small>${m==='standard'?'Estimated 3–5 business days':'Estimated 1–2 business days'}</small></span><b class="delivery-option-price" data-delivery="${m}">${deliveryPriceLabel(m)}</b></label>`).join('')}</fieldset><p class="checkout-small">Illustrative delivery estimates for this storefront preview.</p></section><div class="checkout-form-bottom"><button class="btn btn-dark primary full" type="submit">Continue to payment ${checkoutGlyph('lock')}</button><p class="checkout-small">Your details stay in this session. No order is submitted.</p></div></form><div id="checkoutSummary">${orderSummary()}</div></div></div>`;}
function deliveryPriceLabel(method){const state=checkoutState.details.state;return state?money(3500+(state==='Lagos'?0:1500)+(method==='express'?2500:0)):'Select state';}
function validateDelivery(d){const errors={};for(const [name,label] of [['firstName','first name'],['lastName','last name'],['address','street address'],['city','city']])if(!d[name]?.trim())errors[name]=`Enter your ${label}.`;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email||''))errors.email='Enter a valid email address.';const phone=(d.phone||'').replace(/[\s()+-]/g,'');if(!/^\d{10,15}$/.test(phone))errors.phone='Enter a valid phone number, including its area or country code.';if(!deliveryStates.includes(d.state))errors.state='Choose your delivery state.';return errors;}
function paymentPage(){cleanCart();if(!bag.length){checkoutEmpty();return;}if(!checkoutState.ready||Object.keys(validateDelivery(checkoutState.details)).length){location.hash='checkout';return;}const d=checkoutState.details,t=checkoutTotals();app.innerHTML=`<div class="wrap checkout-wrap"><div class="checkout-top"><a class="btn btn-outline-secondary" href="#checkout">Back to delivery</a><span>${checkoutGlyph('lock')} Checkout preview</span></div>${checkoutSteps(2)}<div class="checkout-heading"><span class="eyebrow">ONE LAST LITTLE DETAIL</span><h1>Your next chapter.</h1><p>Review your delivery details and choose how you'd like to pay.</p></div><div class="checkout-layout"><div><form id="paymentForm" class="checkout-panel payment-panel"><div class="panel-heading"><span class="panel-number">04</span><div><h2>Payment method</h2><p>Choose your preferred way to pay.</p></div></div><fieldset class="payment-options"><legend class="sr-only">Choose a payment method</legend>${[['card','Debit or credit card','Visa, Mastercard or Verve'],['bank','Bank transfer','Transfer from your banking app']].map(([id,label,sub])=>`<label class="choice-card payment-choice"><input type="radio" name="payment" value="${id}" ${checkoutState.method===id?'checked':''}>${checkoutGlyph(id)}<span><b>${label}</b><small>${sub}</small></span></label>`).join('')}</fieldset><div id="paymentMethodDetails">${paymentMethodDetails()}</div><div class="payment-preview-note">${checkoutGlyph('lock')}<div><b>You're viewing a payment preview.</b><p>A payment provider has not been connected. No card details, bank transfer or payment are collected.</p></div></div><button class="btn btn-dark primary full" type="submit">Preview payment — ${money(t.total)}</button><p class="checkout-small">This completes the preview. Your bag stays saved.</p></form><section class="checkout-panel delivery-review"><div class="review-title"><h2>Delivering to</h2><a class="btn btn-outline-secondary" href="#checkout">Edit details</a></div><b>${escapeHTML(d.firstName)} ${escapeHTML(d.lastName)}</b><p>${escapeHTML(d.address)}${d.apartment?', '+escapeHTML(d.apartment):''}<br>${escapeHTML(d.city)}, ${escapeHTML(d.state)}${d.postcode?' '+escapeHTML(d.postcode):''}<br>Nigeria</p><p>${escapeHTML(d.email)}<br>${escapeHTML(d.phone)}</p><div class="delivery-review-method">${icon('truck')}<span>${checkoutState.delivery==='express'?'Express delivery · 1–2 business days':'Standard delivery · 3–5 business days'}</span></div></section></div><div id="checkoutSummary">${orderSummary(true)}</div></div></div>`;}
function paymentMethodDetails(){return checkoutState.method==='card'?`<div class="payment-detail"><div class="payment-card-illustration" aria-hidden="true"><span>MANEMUSE</span>${checkoutGlyph('card')}<b>•••• &nbsp; •••• &nbsp; •••• &nbsp; ••••</b><small>Your card · Private payment window</small></div><p>Card payment will open in the connected provider's payment window. Your card details won't be entered on this page.</p></div>`:`<div class="payment-detail bank-detail">${checkoutGlyph('bank')}<h3>A transfer, made simple.</h3><p>The connected provider will generate bank details and an exact amount for your order. Payment confirmation will appear after verification.</p><span>Bank details are unavailable in this preview.</span></div>`;}
function paymentPreviewPage(){const r=checkoutState.receipt;if(!r){location.hash='bag';return;}app.innerHTML=`<div class="wrap payment-preview-complete"><div class="preview-complete-mark">${checkoutGlyph('check')}</div><span class="eyebrow">CHECKOUT PREVIEW COMPLETE</span><h1>A beautiful choice.</h1><p>Your ${r.method==='card'?'card payment':'bank transfer'} journey is ready to review. No payment was made and no order was placed.</p><div class="preview-receipt"><div><span>Payment method</span><b>${r.method==='card'?'Debit or credit card':'Bank transfer'}</b></div><div><span>Items</span><b>${r.quantity} ${r.quantity===1?'set':'sets'}</b></div><div><span>Delivery</span><b>${money(r.delivery)}</b></div><div><span>Total previewed</span><strong>${money(r.total)}</strong></div><span class="receipt-status">Preview only · Not paid</span></div><div class="preview-complete-actions"><a class="btn btn-dark primary" href="#bag">Return to my bag</a><a class="btn btn-outline-secondary" href="#shop">Keep exploring</a></div><p class="checkout-small">Your bag is still here whenever you're ready.</p></div>`;}
document.addEventListener('input',e=>{if(e.target.closest('#deliveryForm')&&e.target.name){checkoutState.details[e.target.name]=e.target.value;const error=document.getElementById('error-'+e.target.name);if(error){error.textContent='';e.target.removeAttribute('aria-invalid');}}});
document.addEventListener('change',e=>{if(e.target.closest('#deliveryForm')){if(e.target.name==='delivery')checkoutState.delivery=e.target.value;else if(e.target.name==='state')checkoutState.details.state=e.target.value;if(['state','delivery'].includes(e.target.name)){document.querySelector('#checkoutSummary').innerHTML=orderSummary();document.querySelectorAll('[data-delivery]').forEach(el=>el.textContent=deliveryPriceLabel(el.dataset.delivery));}}else if(e.target.closest('#paymentForm')&&e.target.name==='payment'){checkoutState.method=e.target.value;document.querySelector('#paymentMethodDetails').innerHTML=paymentMethodDetails();}});
document.addEventListener('submit',e=>{if(e.target.id==='deliveryForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(d))d[key]=d[key].trim();checkoutState.details=d;checkoutState.delivery=d.delivery;const errors=validateDelivery(d);e.target.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));e.target.querySelectorAll('.field-error').forEach(el=>el.textContent='');const summary=document.querySelector('#checkoutErrors');summary.hidden=!Object.keys(errors).length;if(Object.keys(errors).length){summary.textContent='Please check the highlighted details before continuing.';for(const [name,message] of Object.entries(errors)){document.querySelector('#co-'+name).setAttribute('aria-invalid','true');document.querySelector('#error-'+name).textContent=message;}document.querySelector('#co-'+Object.keys(errors)[0]).focus();checkoutState.ready=false;return;}checkoutState.ready=true;location.hash='payment';}else if(e.target.id==='paymentForm'){e.preventDefault();if(!bag.length||!checkoutState.ready){location.hash='checkout';return;}checkoutState.receipt={...checkoutTotals(),method:checkoutState.method};location.hash='payment-preview';}});
